UNITS = [{'id': 'PEDS-U177', 'ch': 22, 'n': 1, 'title': 'Esophageal Atresia — Definition & Associated Anomalies', 'sec': 'Esophageal Atresia · p95', 'qs': ['PEDS-C22-001', 'PEDS-C22-002', 'PEDS-C22-003', 'PEDS-C22-004', 'PEDS-C22-005', 'PEDS-C22-006', 'PEDS-C22-007', 'PEDS-C22-008'], 'guide': 'Esophageal atresia = discontinuity in the esophagus. Associated anomalies: 1. Tracheo-esophageal fistula (TEF) — m/c defect in mesenchymal separation b/w trachea & esophagus; Gross classification A–F. 2. VACTERL association.'}, {'id': 'PEDS-U178', 'ch': 22, 'n': 2, 'title': 'TEF — Gross Classification (Types A–F)', 'sec': 'Gross classification · p95', 'qs': ['PEDS-C22-009', 'PEDS-C22-010', 'PEDS-C22-011', 'PEDS-C22-012', 'PEDS-C22-013', 'PEDS-C22-014', 'PEDS-C22-015', 'PEDS-C22-016', 'PEDS-C22-017', 'PEDS-C22-018', 'PEDS-C22-019', 'PEDS-C22-020', 'PEDS-C22-021'], 'guide': 'Type A — isolated EA. Type B — proximal TEF with distal EA. Type C — proximal EA with distal TEF (m/c, 85% cases). Type D — proximal and distal TEF (with EA). Type E (or H) — TEF without EA. Type F — esophageal stenosis.'}, {'id': 'PEDS-U179', 'ch': 22, 'n': 3, 'title': 'VACTERL Association', 'sec': 'VACTERL association · p95', 'qs': ['PEDS-C22-022', 'PEDS-C22-023', 'PEDS-C22-024', 'PEDS-C22-025', 'PEDS-C22-026', 'PEDS-C22-027'], 'guide': 'VACTERL: Vertebral anomalies, Imperforate anus, Cardiac defects, Tracheo-esophageal fistula, Renal anomalies, Limb anomalies.'}, {'id': 'PEDS-U180', 'ch': 22, 'n': 4, 'title': 'EA — Clinical Features, Investigations & Treatment', 'sec': 'Clinical features · p96', 'qs': ['PEDS-C22-028', 'PEDS-C22-029', 'PEDS-C22-030', 'PEDS-C22-031', 'PEDS-C22-032', 'PEDS-C22-033', 'PEDS-C22-034', 'PEDS-C22-035', 'PEDS-C22-036', 'PEDS-C22-037'], 'guide': 'Clinical: vomiting (multiple episodes) → aspiration pneumonitis; excessive frothy salivation; antenatal polyhydramnios (inability to swallow amniotic fluid). Investigations — chest X-ray: resistance during NG tube insertion; coiled NG tube in proximal esophagus. Treatment: surgery — anastomosis of esophageal ends + division & ligation of TEF.'}, {'id': 'PEDS-U181', 'ch': 22, 'n': 5, 'title': 'GERD — Clinical Features', 'sec': 'Gastro Esophageal Reflux Disorder (GERD) · p96', 'qs': ['PEDS-C22-038', 'PEDS-C22-039', 'PEDS-C22-040', 'PEDS-C22-041', 'PEDS-C22-042', 'PEDS-C22-043', 'PEDS-C22-044', 'PEDS-C22-045', 'PEDS-C22-046', 'PEDS-C22-047'], 'guide': 'GERD: onset < 6 months (infancy); recurrent vomiting (d/t short esophagus) → aspiration, malnutrition, failure to thrive. Sandifer syndrome: characteristic — spasmodic dystonia (posturing of back muscles): opisthotonus. Opisthotonus also seen in neonatal tetanus & bilirubin-induced neurological damage (BIND).'}, {'id': 'PEDS-U182', 'ch': 22, 'n': 6, 'title': 'GERD — Investigations & Treatment', 'sec': 'Investigations · p96', 'qs': ['PEDS-C22-048', 'PEDS-C22-049', 'PEDS-C22-050', 'PEDS-C22-051', 'PEDS-C22-052', 'PEDS-C22-053', 'PEDS-C22-054', 'PEDS-C22-055', 'PEDS-C22-056', 'PEDS-C22-057', 'PEDS-C22-058', 'PEDS-C22-059', 'PEDS-C22-060', 'PEDS-C22-061'], 'guide': 'Investigations: 24-hr pH monitoring (pH ≤ 4 indicates GERD); pH-MII (multichannel intraluminal impedance) — best test, measures level up to which reflux occurs; upper GI endoscopy — erosions & breaks. Treatment: diet & lifestyle (small frequent feeds, thickened feeds, avoid caffeine/spicy/chocolates) → pharmacological (PPIs omeprazole/lansoprazole × 3 months to prevent recurrence) → surgery for refractory GERD: Nissen fundoplication (fundus wrapped around lower esophagus → ↑ LES tone/pressure → ↓ reflux).'}, {'id': 'PEDS-U183', 'ch': 22, 'n': 7, 'title': 'Foreign Bodies in Esophagus — Features & Natural Course', 'sec': 'Foreign Bodies in Esophagus · p97', 'qs': ['PEDS-C22-062', 'PEDS-C22-063', 'PEDS-C22-064', 'PEDS-C22-065', 'PEDS-C22-066', 'PEDS-C22-067', 'PEDS-C22-068', 'PEDS-C22-069', 'PEDS-C22-070', 'PEDS-C22-071'], 'guide': 'Age ≤ 3 years; common FBs — coins, nuts, small toys. Dangerous: button batteries → coagulative necrosis; multiple magnets → stick across bowel loops → obstruction → perforation; sharp objects. Natural course: > 95% pass & excreted. Impaction sites: cricopharynx, mid-esophagus (tracheal bifurcation), right above LES.'}, {'id': 'PEDS-U184', 'ch': 22, 'n': 8, 'title': 'Foreign Bodies — Clinical Features, Diagnosis & Management', 'sec': 'Clinical features · p97', 'qs': ['PEDS-C22-072', 'PEDS-C22-073', 'PEDS-C22-074', 'PEDS-C22-075', 'PEDS-C22-076', 'PEDS-C22-077', 'PEDS-C22-078', 'PEDS-C22-079', 'PEDS-C22-080', 'PEDS-C22-081', 'PEDS-C22-082'], 'guide': 'H/o ingestion may be absent; may be asymptomatic; if symptomatic — drooling of saliva, refusal of feeds, chest discomfort/pointing; respiratory complaints — recurrent cough/wheeze (pressure on trachea). X-ray: only radio-opaque FBs; esophagogram: filling defect. Management: conservative (blunt & asymptomatic — observe 24 hrs); esophagoscopy removal — symptomatic, impacted > 24 hrs, batteries/magnets/sharp.'}]

